import React, { useState } from 'react';
import { Container, Button, Input, InputGroup, InputGroupText } from 'reactstrap';

const ChatRoom = ({ chatId, otherUserId, loginUserId, goBack }) => {
    const [message, setMessage] = useState('');
    const [messages, setMessages] = useState([]);

    const handleSend = () => {
        if (message.trim() !== '') {
            const newMessage = {
                id: Date.now(),
                sender: loginUserId,
                text: message.trim(),
            };
            setMessages([...messages, newMessage]);
            setMessage('');
        }
    };

    return (
        <Container className="d-flex flex-column" style={{ height: '100vh' }}>
            <Button style={{ fontSize: '10px' }} color="secondary" onClick={goBack}>
                뒤로가기
            </Button>
            <p>
                채팅방 ID: {chatId}, 상대방 ID: {otherUserId}, 내 ID: {loginUserId}
            </p>
            <div
                style={{
                    flex: 1,
                    margin: '20px 0',
                    border: '1px solid #ccc',
                    padding: '10px',
                    overflowY: 'scroll',
                }}
            >
                {messages.map((msg) => (
                    <div
                        key={msg.id}
                        style={{
                            marginBottom: '10px',
                            textAlign: msg.sender === loginUserId ? 'right' : 'left',
                        }}
                    >
                        <div
                            style={{
                                display: 'inline-block',
                                padding: '10px',
                                borderRadius: '10px',
                                backgroundColor: msg.sender === loginUserId ? '#007bff' : '#f1f1f1',
                                color: msg.sender === loginUserId ? '#fff' : '#000',
                            }}
                        >
                            {msg.text}
                        </div>
                    </div>
                ))}
            </div>
            <InputGroup style={{ position: 'sticky', bottom: '10px' }}>
                <Input
                    type="text"
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    placeholder="메시지를 입력하세요"
                />
                <InputGroupText>
                    <Button color="primary" onClick={handleSend}>
                        전송
                    </Button>
                </InputGroupText>
            </InputGroup>
        </Container>
    );
};

export default ChatRoom;
